   var log=new TextBox{Name="deployProgress",IsReadOnly=true,AcceptsReturn=true,Height=120,TextWrapping=TextWrapping.Wrap,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,FontFamily=new System.Windows.Media.FontFamily("Consolas"),Text="Существующая установка не перезаписывается. SSH-пароль/ключ не сохраняются в профиле."};var result=new TextBox{Name="deployResult",IsReadOnly=true,AcceptsReturn=true,MinHeight=84,MaxHeight=160,TextWrapping=TextWrapping.Wrap,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Text=deploymentResult==null?"После успешной установки здесь будут адрес, логин и пароль панели.":DeploymentResultText(deploymentResult)};var progressGroup=new StackPanel{Name="deployProgressSection",Visibility=Visibility.Collapsed,Margin=new Thickness(0,12,0,0)};progressGroup.Children.Add(Text("Журнал установки",16));progressGroup.Children.Add(log);var resultGroup=new StackPanel{Name="deployResultSection",Visibility=deploymentResult==null?Visibility.Collapsed:Visibility.Visible,Margin=new Thickness(0,12,0,0)};resultGroup.Children.Add(Text("Результат установки",16));resultGroup.Children.Add(result);var connectionSection=new StackPanel{Name="deployConnectionsSection",Margin=new Thickness(0,12,0,0)};FillDeploymentConnections(connectionSection);var install=AsyncButton("Установить панель",async()=>{int sshPort,panelNumber;if(!Int32.TryParse(port.Text,out sshPort)||!Int32.TryParse(panelPort.Text,out panelNumber))throw new FormatException("Укажите числовые порты.");var choice=(DeployRecipe)recipe.SelectedItem;var target=new DeployTarget{Host=host.Text.Trim(),Port=sshPort,User=user.Text.Trim(),Password=auth.SelectedIndex==0?password.Password:null,KeyFile=auth.SelectedIndex==1?key.Text:null,KeyPassword=keyPassword.Password,PanelPort=panelNumber,Domain=domain.Text.Trim(),PanelUser=panelUser.Text.Trim(),Provision=readProfiles()};target.Validate();target.