cellation.Dispose();deploymentCancellation=null;form.IsEnabled=true;}});Accent(install);var stop=Button("Остановить",()=>{if(deploymentCancellation!=null)deploymentCancellation.Cancel();},true);var copy=AsyncButton("Копировать реквизиты",()=>{if(deploymentResult==null)throw new InvalidOperationException("Нет подтверждённого результата.");return CopyText(DeploymentResultText(deploymentResult));});var import=AsyncButton("Добавить подключения",async()=>{if(deploymentResult==null||deploymentResult.connections==null||deploymentResult.connections.Length==0)throw new InvalidOperationException("У панели пока нет выданных подключений. Создайте профиль в панели и импортируйте его в разделе «Серверы».");await ImportServerText(String.Join("\n",deploymentResult.connections));});
   import.Visibility=deploymentResult!=null&&deploymentResult.connections!=null&&deploymentResult.connections.Length>0?Visibility.Visible:Visibility.Collapsed;copy.IsEnabled=deploymentResult!=null;Action refreshActions=()=>{import.Visibility=deploymentResult!=null&&deploymentResult.connections!=null&&deploymentResult.connections.Length>0?Visibility.Visible:Visibility.Collapsed;copy.IsEnabled=deploymentResult!=null;};refreshDeploymentActions=refreshActions;
   var footer=Toolbar(install,stop,copy,import);footer.Margin=new Thickness(0,12,0,0);DockPanel.SetDock(footer,Dock.Bottom);panel.Children.Add(footer);var content=new StackPanel{Name="deployPageContent"};content.Children.Add(form);content.Children.Add(progressGroup);content.Children.Add(resultGroup);content.Children.Add(connectionSection);var formScroll=new ScrollViewer{Name="deploymentScroll",Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,Padding=new Thickness(0,0,12,0)};panel.Children.Add(formScroll);body.Children.Add(Card(panel));
